insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('BJ', 'BJ-P-18', 'Achats de biens 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 243 — la taxe ayant grevé en amont les éléments du prix d''une opération imposable est déductible ; art. 244-1-d — pour être déductible, la taxe doit figurer sur une facture normalisée ; art. 245-1 — le droit à déduction naît lorsque la taxe devient exigible chez le fournisseur ; art. 241 pour le taux', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-P-18-BTP90', 'Gazole, huiles et graisses des engins du BTP et de l''industrie 18 %, déductible à 90 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 247-2, dans la rédaction de la loi de finances pour 2026 — le gazole, les huiles et les graisses utilisés par les entreprises industrielles et du bâtiment et des travaux publics pour le fonctionnement de leurs engins ne sont pas exclus du droit à déduction, mais « en ce qui concerne les entreprises des BTP, cette déduction est limitée à 90 % de la TVA supportée figurant sur la facture d''achat » ; le reste est une part du coût', 'S', null, 140, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-P-18-IMMO', 'Immobilisations 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 243 à 245 — déduction de la taxe ayant grevé une immobilisation ; art. 250 — régularisation en cas de cession ou de modification d''activité', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-P-18-ND', 'Achat 18 % non déductible (art. 247)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 247 — exclusions du droit à déduction : véhicules de tourisme ou à usage mixte et leurs pièces (hors loueurs professionnels, crédits-bailleurs, concessionnaires en stock et auto-écoles), leur carburant, le logement et l''hébergement des dirigeants et du personnel non affecté à la sécurité, la réception, la restauration, les spectacles, le mobilier et le matériel de logement, les dons de plus de 10 000 F hors taxe, et les services se rapportant à ces biens exclus. La taxe est une part du coût de ce qui a été acheté', 'S', null, 150, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-P-18-SRV', 'Services extérieurs 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 243 à 245 — déduction de la taxe sur les services acquis pour les besoins de l''exploitation, dès qu''elle est exigible chez le prestataire ; art. 241 pour le taux', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-P-IMP-18', 'Importation 18 % (TVA acquittée en douane)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'import', date '2022-01-01', null, 'Code général des impôts, art. 235-1-a — le fait générateur d''une importation est la mise à la consommation au sens douanier ; art. 236-1-a — la taxe est exigible à l''enregistrement de la déclaration de mise à la consommation ; art. 244-1-a — la déduction se justifie par cette déclaration assortie d''un justificatif de paiement ; art. 245-1 — le droit à déduction naît à la mise à la consommation', null, null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-S-18', 'Ventes de biens 18 %', '{}'::jsonb, 'Livraisons de biens, échanges et travaux à façon au taux unique, TVA au compte 4431', 'percent', 18, 'sale', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 241 — « le taux de la taxe sur la valeur ajoutée est fixé à 18 % », taux unique, inchangé des éditions 2025 et 2026 du Code ; la loi n° 2021-15 du 23 décembre 2021 portant Code général des impôts entre en vigueur le 1er janvier 2022 (art. 659), date retenue ici faute d''avoir vérifié l''origine exacte, antérieure, du taux ; art. 235-1-d — fait générateur à la livraison des biens, des échanges et des travaux à façon ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux normal unique compris entre 15 % et 20 %', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-S-18-SRV', 'Prestations de services 18 %, exigibles à l''encaissement', '{}'::jsonb, 'Prestations de services et travaux immobiliers au taux unique, taxe exigible à l''encaissement', 'percent', 18, 'sale', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 241 pour le taux ; art. 235-1-b et c — fait générateur à l''accomplissement du service ou à l''exécution des travaux immobiliers ; art. 236-1-b — « pour les prestations de service, les travaux immobiliers et les marchés publics de l''État, des collectivités locales et des sociétés, établissements et offices de l''État, [l''exigibilité intervient] à l''encaissement du prix, des acomptes ou avances » ; art. 236-2 — un acompte rend la taxe exigible sur son montant, que l''opération soit matériellement réalisée ou non. Facturée, la taxe attend l''encaissement au compte 4432 « T.V.A. facturée sur prestations de services » ; encaissée, elle est exigible et passe au compte 4431, dont l''intitulé « sur ventes » couvre aussi les ventes de services : le plan n''a pas de compte de taxe en attente propre', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, true, '4432', 'cgi', null, null, null, null),
  ('BJ', 'BJ-S-EXO', 'Opération exonérée (art. 229)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2022-01-01', null, 'Code général des impôts, art. 229, dans la rédaction des lois de finances pour 2023 et pour 2025 — liste des opérations exonérées sans droit à déduction : ventes et prestations sous le seuil d''assujettissement de l''art. 228 (sauf avec l''État et ses démembrements), produits médicaux et alimentaires de première nécessité, enseignement, soins médicaux, presse, livres, timbres, transport public de voyageurs, banque et assurance (soumises à la TAFA), mutations d''immeubles, location d''immeuble nu à usage d''habitation, œuvres d''art vendues par leur auteur, activités agricoles, gaz domestique, dispositifs photosensibles et cellules photovoltaïques, services du marché financier ; art. 481-2-h — la facture porte la mention « exonéré »', 'E', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-S-EXP', 'Exportation, taux zéro', '{}'::jsonb, 'Exportations et opérations assimilées, exonérées avec droit à déduction', 'percent', 0, 'sale', 'export', date '2022-01-01', null, 'Code général des impôts, art. 230 — sont exonérées de la taxe sur la valeur ajoutée par application d''un taux zéro les exportations et opérations assimilées (navires et aéronefs, avitaillement, entrepôts, transit) ; le taux zéro ouvre droit à déduction, à la différence de l''exonération de l''art. 229 ; art. 481-2-h — la facture porte le taux ou la mention « exonéré »', 'G', null, 30, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BJ', 'BJ-S-TAFA-10', 'Intérêts d''une avance à un tiers, TAFA 10 %', '{}'::jsonb, 'Taxe sur les activités financières et assurances, cas général de l''art. 269 — remplace la TVA sur les rémunérations d''opérations financières, y compris hors des banques et établissements financiers', 'percent', 10, 'sale', 'exempt', date '2022-01-01', null, 'Code général des impôts, art. 229-12 — les opérations de banque et d''assurance, soumises à la taxe sur les activités financières et assurances, sont exonérées de la taxe sur la valeur ajoutée ; art. 264-2 — la TAFA est assise sur « les rémunérations perçues sur les opérations financières réalisées en République du Bénin, notamment les commissions et les intérêts perçus sur les crédits, prêts, avances », sans réserver le prêteur aux seules banques et établissements financiers ; art. 267-1 — fait générateur à l''inscription des intérêts au crédit du bénéficiaire ; art. 268-1 — base sur le montant brut hors taxe des intérêts, commissions et autres rémunérations, ou, entre entreprises, par le prêteur ; art. 269 — taux de 10 % « dans tous les autres cas », distinct des 20 % de l''assurance incendie et des 5 % de l''assurance transport, qu''un négoce ordinaire ne rencontre pas ; art. 270-1 — déclarée et recouvrée selon les règles de la TVA, mais sur un imprimé qui lui est propre : elle ne figure sur aucune case de BJ-TVA, seule sa base exonérée y reste, au même titre que les autres exonérations de l''art. 229', null, null, 50, 'other', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

