update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Code général des impôts, art. 481-2-a — la facture normalisée porte « le numéro d''ordre et la date de la facturation », numéro que délivre la machine électronique certifiée de facturation elle-même (art. 482-1) : ni son format ni la continuité de sa séquence ne sont fixés par le Code. sequential dit l''unicité que l''article impose et rien de la façon dont le numéro est produit, qu''Ekwo n''émule pas — voir einvoicing.',
  numbering_source_key          = 'cgi',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Code général des impôts, art. 235-1 — le fait générateur est la livraison pour une vente, l''accomplissement pour une prestation de services et l''exécution pour des travaux immobiliers ; art. 235-2 — sa constatation ne peut en aucun cas être postérieure à l''établissement d''une facture totale ou partielle, qui l''avance donc quand elle est émise avant. invoice_if_issued dit ce principe et sa dérogation ; la taxe des prestations de services et des travaux immobiliers s''en écarte par sa propre exigibilité à l''encaissement (art. 236-1-b), portée par cash_basis sur BJ-S-18-SRV.',
  tax_point_source_key          = 'cgi',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Code général des impôts, art. 481-1 — sauf dérogation du directeur général des Impôts, toute opération d''une personne soumise à l''impôt sur les sociétés, à l''impôt sur les bénéfices d''affaires, à la taxe professionnelle synthétique ou assujettie à la TVA doit faire l''objet d''une facture normalisée ; art. 482-1 — elle est émise et transmise par une machine électronique certifiée de facturation (MECeF), en version matérielle ou dématérialisée (e-MECeF), homologuée par la DGI ; art. 244-1-d — la TVA n''est déductible que si elle figure sur une facture normalisée. C''est un modèle de clearance : la machine certifiante attribue son numéro d''identification (art. 481-2-k) et un code électronique (art. 481-2-l) sans lesquels la facture n''est pas valable. `einvoicing.profile` ne nomme qu''un profil EN 16931 et aucune brique de ce dépôt ne génère, ne certifie ni ne transmet à une MECeF/e-MECeF : le profil, la date d''obligation et le schéma de parties restent vides plutôt que de prétendre couvrir un mécanisme que rien ici n''exécute.',
  einvoice_source_key           = 'cgi',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'BJ';

